import Foundation

/// The bundled emoji dataset: every fully-qualified Unicode emoji with its CLDR
/// name, its search keywords, its group, and its Skin Tone variants.
///
/// Generated by `Scripts/generate-emoji-index.swift` and shipped as
/// `emoji-index.json`. There is no Apple API for this — see
/// `docs/adr/0005-bundled-emoji-dataset.md` for why, and for why the Skin Tone
/// variants are a lookup table rather than something we build by hand.
final class EmojiIndex {
    enum LoadError: Error, CustomStringConvertible {
        case resourceMissing

        var description: String {
            switch self {
            case .resourceMissing: "emoji-index.json is not in the bundle"
            }
        }
    }

    static let resourceName = "emoji-index"
    static let licenseResourceName = "emoji-data-license"

    let unicodeVersion: String
    let cldrVersion: String
    /// Category names in the canonical Unicode order.
    let groups: [String]
    /// Every Emoji, in the canonical Unicode order. Skin Tone variants are not
    /// in here — they never appear as separate Results.
    let all: [Emoji]

    private let positionByString: [String: Int]

    /// Skin Tone variants keyed by the base emoji's own string.
    ///
    /// Never synthesised. In a ZWJ sequence the modifier goes after the *base*
    /// scalar mid-string, and some Emoji 17 sequences take two independent
    /// tones, so the only safe way to get one is to look it up.
    private let variantsByBase: [String: [String]]

    /// The app-wide index. Decoding ~1,900 rows takes a few milliseconds and
    /// happens once, the first time something asks for an Emoji.
    static let shared: EmojiIndex = (try? bundled()) ?? EmojiIndex.empty

    /// Decodes the dataset off the main thread.
    ///
    /// Nothing on the launch path reads `shared` any more — see
    /// `EmojiSearchVM.index` — so without this the first Emoji Mode would pay
    /// for the parse instead, on the main thread, as the Panel opened. Calling
    /// this at launch moves the cost to a background queue and leaves it decoded
    /// by the time anyone asks.
    ///
    /// Safe to race with any other access: `shared` is a `static let`, so
    /// whichever caller arrives second waits for the first rather than decoding
    /// again.
    static func prewarm() {
        DispatchQueue.global(qos: .utility).async { _ = shared }
    }

    // MARK: - Loading

    private struct Payload: Decodable {
        struct Row: Decodable {
            let e: String
            let n: String
            let k: [String]
            let g: Int
        }

        let unicodeVersion: String
        let cldrVersion: String
        let groups: [String]
        let emoji: [Row]
        let skinTones: [String: [String]]
    }

    private init(payload: Payload) {
        unicodeVersion = payload.unicodeVersion
        cldrVersion = payload.cldrVersion
        groups = payload.groups
        all = payload.emoji.map {
            Emoji(string: $0.e, name: $0.n, keywords: $0.k, groupIndex: $0.g)
        }
        variantsByBase = payload.skinTones

        var positions: [String: Int] = [:]
        positions.reserveCapacity(all.count)
        for (offset, emoji) in all.enumerated() { positions[emoji.string] = offset }
        positionByString = positions
    }

    static func decode(_ data: Data) throws -> EmojiIndex {
        EmojiIndex(payload: try JSONDecoder().decode(Payload.self, from: data))
    }

    static func bundled(in bundle: Bundle = .main) throws -> EmojiIndex {
        guard let url = bundle.url(forResource: resourceName, withExtension: "json") else {
            throw LoadError.resourceMissing
        }
        return try decode(Data(contentsOf: url))
    }

    /// The Unicode and CLDR copyright notice that has to ship with the data.
    /// Settings surfaces it.
    static func licenseText(in bundle: Bundle = .main) -> String? {
        guard let url = bundle.url(forResource: licenseResourceName, withExtension: "txt") else {
            return nil
        }
        return try? String(contentsOf: url, encoding: .utf8)
    }

    /// What `shared` falls back to when the resource is missing. Search returns
    /// nothing rather than the app refusing to launch.
    static let empty = EmojiIndex(payload: Payload(
        unicodeVersion: "",
        cldrVersion: "",
        groups: [],
        emoji: [],
        skinTones: [:]
    ))

    var isEmpty: Bool { all.isEmpty }

    // MARK: - Lookup

    func emoji(_ string: String) -> Emoji? {
        positionByString[string].map { all[$0] }
    }

    func groupName(_ index: Int) -> String {
        groups.indices.contains(index) ? groups[index] : ""
    }

    /// Every Emoji grouped by category, in canonical order. The grid's
    /// empty-query layout.
    func byGroup() -> [(group: String, emoji: [Emoji])] {
        var buckets: [[Emoji]] = Array(repeating: [], count: groups.count)
        for emoji in all where buckets.indices.contains(emoji.groupIndex) {
            buckets[emoji.groupIndex].append(emoji)
        }
        return zip(groups, buckets)
            .filter { !$0.1.isEmpty }
            .map { (group: $0.0, emoji: $0.1) }
    }

    // MARK: - Skin Tone

    /// Whether the six-tone override applies to this Emoji — that is, whether
    /// the dataset has variants for it. Equivalent to `isEmojiModifierBase` on
    /// the base scalar, but true for ZWJ sequences too, which that property
    /// cannot answer.
    func hasSkinTones(_ emoji: Emoji) -> Bool {
        variantsByBase[emoji.string]?.isEmpty == false
    }

    /// Every stored variant of an Emoji, mixed-tone sequences included.
    func variants(of emoji: Emoji) -> [String] {
        variantsByBase[emoji.string] ?? []
    }

    /// This Emoji in one Skin Tone.
    ///
    /// Picks the variant whose modifiers are *all* that tone, so a sequence
    /// taking two independent tones resolves to the matching pair rather than
    /// to an arbitrary mixed one. Falls back to the untoned emoji when the tone
    /// does not apply.
    func emoji(_ emoji: Emoji, in tone: SkinTone) -> Emoji {
        guard let modifier = tone.modifier else { return emoji }
        let match = variants(of: emoji).first { variant in
            var sawModifier = false
            for scalar in variant.unicodeScalars where SkinTone.isModifier(scalar) {
                if scalar != modifier { return false }
                sawModifier = true
            }
            return sawModifier
        }
        return match.map(emoji.wearing) ?? emoji
    }
}
